import{_ as e,o,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Overview","description":"The four ways to connect ApptiveGrid to other systems.","frontmatter":{"title":"Overview","description":"The four ways to connect ApptiveGrid to other systems."},"headers":[],"relativePath":"en/integrationen/ueberblick.md","filePath":"en/integrationen/ueberblick.md","lastUpdated":1787319236000}'),n={name:"en/integrationen/ueberblick.md"};function s(i,t,d,l,h,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="integrations-at-a-glance" tabindex="-1">Integrations at a glance <a class="header-anchor" href="#integrations-at-a-glance" aria-label="Permalink to &quot;Integrations at a glance&quot;">​</a></h1><p>ApptiveGrid can be connected to other systems in four ways.</p><table tabindex="0"><thead><tr><th>Way</th><th>Direction</th><th>Set up in</th></tr></thead><tbody><tr><td><strong>Integration steps in a Flow</strong></td><td>ApptiveGrid → outside system</td><td><a href="/en/flows/aktionen">Flow editor</a></td></tr><tr><td><strong>Webhooks</strong></td><td>ApptiveGrid → outside system</td><td><a href="/en/integrationen/webhooks">Space settings</a></td></tr><tr><td><strong>Webhook trigger</strong></td><td>Outside system → ApptiveGrid</td><td><a href="/en/flows/webhook-trigger">Flow editor</a></td></tr><tr><td><strong>API</strong></td><td>both directions</td><td><a href="/en/integrationen/api-zugangsdaten">API credentials</a></td></tr></tbody></table><hr><h2 id="which-way-for-what" tabindex="-1">Which way for what <a class="header-anchor" href="#which-way-for-what" aria-label="Permalink to &quot;Which way for what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Way</th></tr></thead><tbody><tr><td>Send a message to Slack or Teams</td><td><strong>Integration step</strong></td></tr><tr><td>Create a contact in HubSpot</td><td><strong>Integration step</strong></td></tr><tr><td>Call any system</td><td><strong>Integration step</strong> <em>HTTP request</em></td></tr><tr><td>Notify another system of changes</td><td><strong>Webhook</strong></td></tr><tr><td>Start a Flow from outside</td><td><strong>Webhook trigger</strong></td></tr><tr><td>Your own application that reads and writes data</td><td><strong>API</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Check first whether a Flow is enough</p><p>The API is powerful, but requires programming skills. For most connections, a Flow with the <strong>HTTP request</strong> step is enough — with no code of your own.</p></div><hr><h2 id="credentials-for-integration-steps" tabindex="-1">Credentials for integration steps <a class="header-anchor" href="#credentials-for-integration-steps" aria-label="Permalink to &quot;Credentials for integration steps&quot;">​</a></h2><p>The ready-made integration steps differ in whether you need your own credentials.</p><h3 id="without-your-own-credentials" tabindex="-1">Without your own credentials <a class="header-anchor" href="#without-your-own-credentials" aria-label="Permalink to &quot;Without your own credentials&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Service</th><th>You provide</th></tr></thead><tbody><tr><td><strong>OpenAI</strong></td><td>Only the prompt and optional instructions</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">OpenAI runs through ApptiveGrid</p><p>You don&#39;t need your <strong>own</strong> OpenAI contract or API key. The step is ready to use as soon as your plan includes it.</p></div><div class="danger custom-block"><p class="custom-block-title">Check what data you&#39;re passing along, regardless</p><p>The content of a prompt leaves ApptiveGrid and is sent to an external service. Don&#39;t pass along personal or confidential data without a prior data protection review.</p></div><h3 id="with-your-own-credentials" tabindex="-1">With your own credentials <a class="header-anchor" href="#with-your-own-credentials" aria-label="Permalink to &quot;With your own credentials&quot;">​</a></h3><p>For these services, you need your own account and enter the credentials in the respective Flow step:</p><table tabindex="0"><thead><tr><th>Service</th><th>You enter</th><th>Where to get it</th></tr></thead><tbody><tr><td><strong>Slack</strong></td><td>Webhook URL</td><td>Slack admin, set up an incoming webhook</td></tr><tr><td><strong>MS Teams</strong></td><td>Webhook URL</td><td>Teams channel, set up a connector</td></tr><tr><td><strong>Firebase Cloud Messaging</strong></td><td>API key, device tokens or topic</td><td>Firebase console</td></tr><tr><td><strong>HubSpot</strong></td><td>API token</td><td>HubSpot account</td></tr><tr><td><strong>Magenta Business</strong> (SMS, Verify)</td><td>API key and secret</td><td>Contract with the provider</td></tr><tr><td><strong>DATEV Payroll</strong></td><td>Access key and password</td><td>Your DATEV account</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Credentials live in the Flow</p><p>The keys you enter are part of the Flow&#39;s configuration. Anyone with the <strong>Manage</strong> role in the Space can open the Flow.</p><p>Put Flows with sensitive credentials in a Space with a deliberately small circle of members — and use keys with restricted permissions wherever possible.</p></div><div class="tip custom-block"><p class="custom-block-title">Get credentials before you start building</p><p>The most common stumbling block: the Flow is fully built, but the Slack webhook or HubSpot token is still missing — and obtaining it can take days in some organizations.</p><p>Sort that out before you start building.</p></div><h3 id="usable-without-configuration" tabindex="-1">Usable without configuration <a class="header-anchor" href="#usable-without-configuration" aria-label="Permalink to &quot;Usable without configuration&quot;">​</a></h3><p>These steps need neither a contract nor a key:</p><p><strong>QR Code</strong>, <strong>PDF to text</strong>, <strong>URL to PDF</strong>, <strong>Import CSV file</strong>, <strong>Speech to text</strong>, <strong>Document Analyzer</strong>, <strong>Calendar Event</strong>, <strong>Wait</strong>, <strong>JavaScript</strong></p><p>Some of these are plan-restricted.</p><hr><h2 id="when-no-ready-made-step-fits" tabindex="-1">When no ready-made step fits <a class="header-anchor" href="#when-no-ready-made-step-fits" aria-label="Permalink to &quot;When no ready-made step fits&quot;">​</a></h2><p>The <strong>HTTP request</strong> step calls arbitrary systems. You specify:</p><table tabindex="0"><thead><tr><th>Field</th><th>Content</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td>Target address</td></tr><tr><td><strong>Method</strong></td><td>GET, POST, …</td></tr><tr><td><strong>Content type</strong></td><td>Format of the data</td></tr><tr><td><strong>Headers</strong></td><td>Header fields, e.g. for authentication</td></tr><tr><td><strong>Body</strong></td><td>The data to send</td></tr><tr><td><strong>Username</strong> / <strong>Password</strong></td><td>For basic authentication</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">The path to almost any service</p><p>Anything with an open interface can be connected this way — including automation platforms that in turn reach hundreds of other services.</p><p>The editor itself points this out: <em>Nothing fitting found?</em> with the option to submit a request.</p></div><hr><h2 id="where-data-lives" tabindex="-1">Where data lives <a class="header-anchor" href="#where-data-lives" aria-label="Permalink to &quot;Where data lives&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">File attachments</p><p>Uploaded files live in object storage in the <strong>Europe (Frankfurt)</strong> region. Uploads from public forms use a separate, unauthenticated path.</p><p>For data protection inquiries, contact support — this documentation doesn&#39;t replace a legal assessment.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/flows/aktionen">Actions</a> — all integration steps in detail</li><li><a href="/en/integrationen/webhooks">Webhooks</a></li><li><a href="/en/integrationen/api-zugangsdaten">API credentials</a></li></ul>',33)])])}const u=e(n,[["render",s]]);export{g as __pageData,u as default};
